# ! [doc = " This file declares the `ScopeTree` type, which describes"] # ! [doc = " the parent links in the region hierarchy."] # ! [doc = ""] # ! [doc = " For more information about how MIR-based region-checking works,"] # ! [doc = " see the [rustc dev guide]."] # ! [doc = ""] # ! [doc = " [rustc dev guide]: https://rustc-dev-guide.rust-lang.org/borrow_check.html"] use split_decls_genesis :: ourprelude :: * ; use std :: fmt ; use rustc_data_structures :: fx :: FxIndexMap ; use rustc_data_structures :: unord :: UnordMap ; use rustc_hir as hir ; use rustc_hir :: { HirId , HirIdMap , Node } ; use rustc_macros :: { HashStable , TyDecodable , TyEncodable } ; use rustc_span :: { DUMMY_SP , Span } ; use tracing :: debug ; use crate :: mir :: BackwardIncompatibleDropReason ; use crate :: ty :: TyCtxt ; #[doc = " Represents a statically-describable scope that can be used to"] #[doc = " bound the lifetime/region for values."] #[doc = ""] #[doc = " `Node(node_id)`: Any AST node that has any scope at all has the"] #[doc = " `Node(node_id)` scope. Other variants represent special cases not"] #[doc = " immediately derivable from the abstract syntax tree structure."] #[doc = ""] #[doc = " `DestructionScope(node_id)` represents the scope of destructors"] #[doc = " implicitly-attached to `node_id` that run immediately after the"] #[doc = " expression for `node_id` itself. Not every AST node carries a"] #[doc = " `DestructionScope`, but those that are `terminating_scopes` do;"] #[doc = " see discussion with `ScopeTree`."] #[doc = ""] #[doc = " `Remainder { block, statement_index }` represents"] #[doc = " the scope of user code running immediately after the initializer"] #[doc = " expression for the indexed statement, until the end of the block."] #[doc = ""] #[doc = " So: the following code can be broken down into the scopes beneath:"] #[doc = ""] #[doc = " ```text"] #[doc = " let a = f().g( 'b: { let x = d(); let y = d(); x.h(y)  }   ) ;"] #[doc = ""] #[doc = "                                                              +-+ (D12.)"] #[doc = "                                                        +-+       (D11.)"] #[doc = "                                              +---------+         (R10.)"] #[doc = "                                              +-+                  (D9.)"] #[doc = "                                   +----------+                    (M8.)"] #[doc = "                                 +----------------------+          (R7.)"] #[doc = "                                 +-+                               (D6.)"] #[doc = "                      +----------+                                 (M5.)"] #[doc = "                    +-----------------------------------+          (M4.)"] #[doc = "         +--------------------------------------------------+      (M3.)"] #[doc = "         +--+                                                      (M2.)"] #[doc = " +-----------------------------------------------------------+     (M1.)"] #[doc = ""] #[doc = "  (M1.): Node scope of the whole `let a = ...;` statement."] #[doc = "  (M2.): Node scope of the `f()` expression."] #[doc = "  (M3.): Node scope of the `f().g(..)` expression."] #[doc = "  (M4.): Node scope of the block labeled `'b:`."] #[doc = "  (M5.): Node scope of the `let x = d();` statement"] #[doc = "  (D6.): DestructionScope for temporaries created during M5."] #[doc = "  (R7.): Remainder scope for block `'b:`, stmt 0 (let x = ...)."] #[doc = "  (M8.): Node scope of the `let y = d();` statement."] #[doc = "  (D9.): DestructionScope for temporaries created during M8."] #[doc = " (R10.): Remainder scope for block `'b:`, stmt 1 (let y = ...)."] #[doc = " (D11.): DestructionScope for temporaries and bindings from block `'b:`."] #[doc = " (D12.): DestructionScope for temporaries created during M1 (e.g., f())."] #[doc = " ```"] #[doc = ""] #[doc = " Note that while the above picture shows the destruction scopes"] #[doc = " as following their corresponding node scopes, in the internal"] #[doc = " data structures of the compiler the destruction scopes are"] #[doc = " represented as enclosing parents. This is sound because we use the"] #[doc = " enclosing parent relationship just to ensure that referenced"] #[doc = " values live long enough; phrased another way, the starting point"] #[doc = " of each range is not really the important thing in the above"] #[doc = " picture, but rather the ending point."] #[derive (Clone , PartialEq , PartialOrd , Eq , Ord , Hash , Copy , TyEncodable , TyDecodable)] #[derive (HashStable)] pub struct Scope { pub local_id : hir :: ItemLocalId , pub data : ScopeData , } impl fmt :: Debug for Scope { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match self . data { ScopeData :: Node => write ! (fmt , "Node({:?})" , self . local_id) , ScopeData :: CallSite => write ! (fmt , "CallSite({:?})" , self . local_id) , ScopeData :: Arguments => write ! (fmt , "Arguments({:?})" , self . local_id) , ScopeData :: Destruction => write ! (fmt , "Destruction({:?})" , self . local_id) , ScopeData :: IfThen => write ! (fmt , "IfThen({:?})" , self . local_id) , ScopeData :: IfThenRescope => write ! (fmt , "IfThen[edition2024]({:?})" , self . local_id) , ScopeData :: MatchGuard => write ! (fmt , "MatchGuard({:?})" , self . local_id) , ScopeData :: Remainder (fsi) => write ! (fmt , "Remainder {{ block: {:?}, first_statement_index: {}}}" , self . local_id , fsi . as_u32 () ,) , } } } #[derive (Clone , PartialEq , PartialOrd , Eq , Ord , Hash , Debug , Copy , TyEncodable , TyDecodable)] #[derive (HashStable)] pub enum ScopeData { Node , #[doc = " Scope of the call-site for a function or closure"] #[doc = " (outlives the arguments as well as the body)."] CallSite , #[doc = " Scope of arguments passed to a function or closure"] #[doc = " (they outlive its body)."] Arguments , #[doc = " Scope of destructors for temporaries of node-id."] Destruction , #[doc = " Scope of the condition and then block of an if expression"] #[doc = " Used for variables introduced in an if-let expression."] IfThen , #[doc = " Scope of the condition and then block of an if expression"] #[doc = " Used for variables introduced in an if-let expression,"] #[doc = " whose lifetimes do not cross beyond this scope."] IfThenRescope , #[doc = " Scope of the condition and body of a match arm with a guard"] #[doc = " Used for variables introduced in an if-let guard,"] #[doc = " whose lifetimes do not cross beyond this scope."] MatchGuard , #[doc = " Scope following a `let id = expr;` binding in a block."] Remainder (FirstStatementIndex) , } rustc_index :: newtype_index ! { #[doc = " Represents a subscope of `block` for a binding that is introduced"] #[doc = " by `block.stmts[first_statement_index]`. Such subscopes represent"] #[doc = " a suffix of the block. Note that each subscope does not include"] #[doc = " the initializer expression, if any, for the statement indexed by"] #[doc = " `first_statement_index`."] #[doc = ""] #[doc = " For example, given `{ let (a, b) = EXPR_1; let c = EXPR_2; ... }`:"] #[doc = ""] #[doc = " * The subscope with `first_statement_index == 0` is scope of both"] #[doc = "   `a` and `b`; it does not include EXPR_1, but does include"] #[doc = "   everything after that first `let`. (If you want a scope that"] #[doc = "   includes EXPR_1 as well, then do not use `Scope::Remainder`,"] #[doc = "   but instead another `Scope` that encompasses the whole block,"] #[doc = "   e.g., `Scope::Node`."] #[doc = ""] #[doc = " * The subscope with `first_statement_index == 1` is scope of `c`,"] #[doc = "   and thus does not include EXPR_2, but covers the `...`."] #[derive (HashStable)] #[encodable] #[orderable] pub struct FirstStatementIndex { } } rustc_data_structures :: static_assert_size ! (ScopeData , 4) ; impl Scope { pub fn hir_id (& self , scope_tree : & ScopeTree) -> Option < HirId > { scope_tree . root_body . map (| hir_id | HirId { owner : hir_id . owner , local_id : self . local_id }) } #[doc = " Returns the span of this `Scope`. Note that in general the"] #[doc = " returned span may not correspond to the span of any `NodeId` in"] #[doc = " the AST."] pub fn span (& self , tcx : TyCtxt < '_ > , scope_tree : & ScopeTree) -> Span { let Some (hir_id) = self . hir_id (scope_tree) else { return DUMMY_SP ; } ; let span = tcx . hir_span (hir_id) ; if let ScopeData :: Remainder (first_statement_index) = self . data && let Node :: Block (blk) = tcx . hir_node (hir_id) { let stmt_span = blk . stmts [first_statement_index . index ()] . span ; if span . lo () <= stmt_span . lo () && stmt_span . lo () <= span . hi () { return span . with_lo (stmt_span . lo ()) ; } } span } } #[doc = " The region scope tree encodes information about region relationships."] #[derive (Default , Debug , HashStable)] pub struct ScopeTree { #[doc = " If not empty, this body is the root of this region hierarchy."] pub root_body : Option < HirId > , #[doc = " Maps from a scope ID to the enclosing scope id;"] #[doc = " this is usually corresponding to the lexical nesting, though"] #[doc = " in the case of closures the parent scope is the innermost"] #[doc = " conditional expression or repeating block. (Note that the"] #[doc = " enclosing scope ID for the block associated with a closure is"] #[doc = " the closure itself.)"] pub parent_map : FxIndexMap < Scope , Scope > , #[doc = " Maps from a variable or binding ID to the block in which that"] #[doc = " variable is declared."] var_map : FxIndexMap < hir :: ItemLocalId , Scope > , #[doc = " Maps from bindings to their future scopes after #145838 for the"] #[doc = " `macro_extended_temporary_scopes` lint."] var_compatibility_map : FxIndexMap < hir :: ItemLocalId , Scope > , #[doc = " Identifies expressions which, if captured into a temporary, ought to"] #[doc = " have a temporary whose lifetime extends to the end of the enclosing *block*,"] #[doc = " and not the enclosing *statement*. Expressions that are not present in this"] #[doc = " table are not rvalue candidates. The set of rvalue candidates is computed"] #[doc = " during type check based on a traversal of the AST."] pub rvalue_candidates : HirIdMap < RvalueCandidate > , #[doc = " Backwards incompatible scoping that will be introduced in future editions."] #[doc = " This information is used later for linting to identify locals and"] #[doc = " temporary values that will receive backwards-incompatible drop orders."] pub backwards_incompatible_scope : UnordMap < hir :: ItemLocalId , Scope > , } #[doc = " See the `rvalue_candidates` field for more information on rvalue"] #[doc = " candidates in general."] #[doc = " The `lifetime` field is None to indicate that certain expressions escape"] #[doc = " into 'static and should have no local cleanup scope."] #[derive (Debug , Copy , Clone , HashStable)] pub struct RvalueCandidate { pub target : hir :: ItemLocalId , pub lifetime : Option < Scope > , pub compat : ScopeCompatibility , } #[doc = " Marks extended temporary scopes that will be shortened by #145838 and thus need to be linted on"] #[doc = " by the `macro_extended_temporary_scopes` future-incompatibility warning."] #[derive (TyEncodable , TyDecodable , Clone , Copy , Debug , Eq , PartialEq , HashStable)] pub enum ScopeCompatibility { #[doc = " Marks a scope that was extended past a temporary destruction scope by a non-extending"] #[doc = " `super let` initializer."] FutureIncompatible { shortens_to : Scope } , #[doc = " Marks an extended temporary scope that was not extended by a non-extending `super let`"] #[doc = " initializer."] FutureCompatible , } impl ScopeTree { pub fn record_scope_parent (& mut self , child : Scope , parent : Option < Scope >) { debug ! ("{:?}.parent = {:?}" , child , parent) ; if let Some (p) = parent { let prev = self . parent_map . insert (child , p) ; assert ! (prev . is_none ()) ; } } pub fn record_var_scope (& mut self , var : hir :: ItemLocalId , lifetime : Scope) { debug ! ("record_var_scope(sub={:?}, sup={:?})" , var , lifetime) ; assert ! (var != lifetime . local_id) ; self . var_map . insert (var , lifetime) ; } pub fn record_future_incompatible_var_scope (& mut self , var : hir :: ItemLocalId , lifetime : Scope) { assert ! (var != lifetime . local_id) ; self . var_compatibility_map . insert (var , lifetime) ; } pub fn record_rvalue_candidate (& mut self , var : HirId , candidate : RvalueCandidate) { debug ! ("record_rvalue_candidate(var={var:?}, candidate={candidate:?})") ; if let Some (lifetime) = & candidate . lifetime { assert ! (var . local_id != lifetime . local_id) } self . rvalue_candidates . insert (var , candidate) ; } #[doc = " Returns the narrowest scope that encloses `id`, if any."] pub fn opt_encl_scope (& self , id : Scope) -> Option < Scope > { self . parent_map . get (& id) . cloned () } #[doc = " Returns the lifetime of the local variable `var_id`, if any, as well as whether it is"] #[doc = " shortening after #145838."] pub fn var_scope (& self , var_id : hir :: ItemLocalId) -> (Option < Scope > , ScopeCompatibility) { let compat = match self . var_compatibility_map . get (& var_id) { Some (& shortens_to) => ScopeCompatibility :: FutureIncompatible { shortens_to } , None => ScopeCompatibility :: FutureCompatible , } ; (self . var_map . get (& var_id) . cloned () , compat) } #[doc = " Returns `true` if `subscope` is equal to or is lexically nested inside `superscope`, and"] #[doc = " `false` otherwise."] #[doc = ""] #[doc = " Used by clippy."] pub fn is_subscope_of (& self , subscope : Scope , superscope : Scope) -> bool { let mut s = subscope ; debug ! ("is_subscope_of({:?}, {:?})" , subscope , superscope) ; while superscope != s { match self . opt_encl_scope (s) { None => { debug ! ("is_subscope_of({:?}, {:?}, s={:?})=false" , subscope , superscope , s) ; return false ; } Some (scope) => s = scope , } } debug ! ("is_subscope_of({:?}, {:?})=true" , subscope , superscope) ; true } #[doc = " Returns the scope of non-lifetime-extended temporaries within a given scope, as well as"] #[doc = " whether we've recorded a potential backwards-incompatible change to lint on."] #[doc = " Returns `None` when no enclosing temporary scope is found, such as for static items."] pub fn default_temporary_scope (& self , inner : Scope ,) -> (Option < Scope > , Option < (Scope , BackwardIncompatibleDropReason) >) { let mut id = inner ; let mut backwards_incompatible = None ; while let Some (& p) = self . parent_map . get (& id) { match p . data { ScopeData :: Destruction => { debug ! ("temporary_scope({inner:?}) = {id:?} [enclosing]") ; return (Some (id) , backwards_incompatible) ; } ScopeData :: IfThenRescope | ScopeData :: MatchGuard => { debug ! ("temporary_scope({inner:?}) = {p:?} [enclosing]") ; return (Some (p) , backwards_incompatible) ; } ScopeData :: Node | ScopeData :: CallSite | ScopeData :: Arguments | ScopeData :: IfThen | ScopeData :: Remainder (_) => { if backwards_incompatible . is_none () { backwards_incompatible = self . backwards_incompatible_scope . get (& p . local_id) . map (| & s | (s , BackwardIncompatibleDropReason :: Edition2024)) ; } id = p } } } debug ! ("temporary_scope({inner:?}) = None") ; (None , backwards_incompatible) } }